<script lang="ts">
 import { t } from '$lib/i18n/ns/file-storage';
 import StatusChip from '$lib/components/ui/StatusChip.svelte'; import Button from '$lib/components/ui/Button.svelte'; import type { ShareNetwork } from '$lib/types/shareNetwork'; import SelectionCheckbox from '$lib/components/ui/SelectionCheckbox.svelte'; import ActivityIndicator from '$lib/components/ui/ActivityIndicator.svelte';
 let { networks, deleting, onDelete, selectedIds, selectableIds, selectionDisabled, onToggleSelect, onToggleAll }: { networks: ShareNetwork[]; deleting: string | null; onDelete: (id: string, name: string) => Promise<void>; selectedIds: ReadonlySet<string>; selectableIds: ReadonlySet<string>; selectionDisabled: boolean; onToggleSelect: (id: string) => void; onToggleAll: () => void; } = $props(); const selectedCount = $derived([...selectedIds].filter((id) => selectableIds.has(id)).length);
</script>
<div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b border-line text-ink-2 text-xs uppercase tracking-wide"><th class="text-left py-3 pr-3"><SelectionCheckbox checked={selectableIds.size > 0 && selectedCount === selectableIds.size} indeterminate={selectedCount > 0 && selectedCount < selectableIds.size} disabled={selectionDisabled || selectableIds.size === 0} onclick={onToggleAll} ariaLabel={t('networkTable.selectAll')} /></th><th class="text-left py-3 pr-6">{t('networkTable.name')}</th><th class="text-left py-3 pr-6">{t('networkTable.status')}</th><th class="text-left py-3 pr-6">{t('networkTable.networkId')}</th><th class="text-left py-3 pr-6">{t('networkTable.subnetId')}</th><th class="text-left py-3 pr-6">{t('networkTable.createdAt')}</th><th class="text-right py-3">{t('networkTable.actions')}</th></tr></thead><tbody class="motion-stagger">{#each networks as net (net.id)}<tr class="resource-selection-surface border-b border-line/50 hover:bg-surface-sunken/30 transition-colors" data-selected={selectedIds.has(net.id)}><td class="py-3 pr-3"><SelectionCheckbox checked={selectedIds.has(net.id)} disabled={selectionDisabled} onclick={() => onToggleSelect(net.id)} ariaLabel={t('networkTable.select', { name: net.name || net.id })} /></td><td class="py-3 pr-6 font-medium text-ink-0">{#if net.name}<span>{net.name}</span>{:else}<span class="font-mono text-xs text-ink-2">{net.id.slice(0, 8)}</span>{/if}{#if net.description}<div class="text-xs text-ink-2">{net.description}</div>{/if}</td><td class="py-3 pr-6"><StatusChip status={net.status || null} /></td><td class="py-3 pr-6 font-mono text-xs text-ink-2">{net.neutron_net_id?.slice(0, 20) ?? '-'}...</td><td class="py-3 pr-6 font-mono text-xs text-ink-2">{net.neutron_subnet_id?.slice(0, 20) ?? '-'}...</td><td class="py-3 pr-6 text-xs text-ink-2">{net.created_at ? net.created_at.split('T')[0] : '-'}</td><td class="py-3 text-right"><Button variant="danger-outline" size="xs" disabled={deleting === 